/-- Observation type-A. -/
def channel (A : Form M) (x : Grid M) : Law (Grid M) :=
  (label A).send (fun z => x+z)

/-- Observation law weighted by the local subpiece. -/
def omegaObs (p : Node) (a : Grid M → ℝ) (α : ℝ) (A : Form M) (y z : Grid M) :=
    wt p a α y * channel A y z
def Mz (p : Node) (a : Grid M → ℝ) (α : ℝ) (A : Form M) (z : Grid M) :=
    ∑ y, omegaObs p a α A y z
def fz (p : Node) (a : Grid M → ℝ) (α : ℝ) (A : Form M) (u z : Grid M) : ℂ :=
    ∑ y, (omegaObs p a α A y z:ℂ) * chi u y

/-- Observation mass relative to s.norm. -/
def hist (s : Scene M) (k : Grid M → Law α) (i : α) :=
    ∑ x : Grid M, wt s.here s.wage s.norm x*k x i
def diff (s : Scene M) (k : Grid M → Law α) (i : α) :=
    (hist (s.smaller false) k i - hist (s.smaller true) k i)/2

def fisher (s : Scene M) (k : Grid M → Law α) :=
    ∑ i : α, (diff s k i)^2 / hist s k i

def givenD (s : Scene M) := deficit s (channel s.fund.mood)

def massInfo (s : Scene M) :=
    1/4*(s.norm/s.mass)*fisher s (channel s.fund.mood)

/-- The equally weighted mean, bundled with its unit-ball bound. -/
def ballMean (hD : 0 < D) (x : Fin D → UnitBall E) : UnitBall E :=
  ⟨finMean (fun i => (x i : E)), finMean_mem_unitBall hD x⟩

def globalColor (hD : 0 < D) (f : UnitBall E → UnitBall E)
    (n : ℕ) (q : IntervalIndex D) (g : F) : UnitBall E :=
  optionFamilyColor hD f (imagePartitionOption g n) q

def pinLaw (μ : Ω → ℝ) (π : Ω → Perm V) (P : Set V) : MvPolynomial (P ⊕ P) ℂ :=
  lawSymbol (fun ω => μ ω * (2 : ℝ) ^ missingCount (π ω) P)
    (fun ω => nextPermutation (π ω) P)
